fn main() {
    let x = 5;
    println!("The value of x is: {}", x);

    // This will cause a compile error!
    // x = 6;
    // error: cannot assign twice to immutable variable `x`
}

fn main() {
    let mut x = 5;
    println!("The value of x is: {}", x);

    x = 6;  // This works because x is mutable
    println!("The value of x is now: {}", x);
}

const MAX_POINTS: u32 = 100_000;

fn main() {
    println!("Maximum points: {}", MAX_POINTS);

    // Constants can be used in any scope
    const PI: f64 = 3.14159;
    println!("Value of PI: {}", PI);
}

fn main() {
    let x = 5;
    let x = x + 1;      // Shadowing: new x = 6
    let x = x * 2;      // Shadowing: new x = 12
    println!("The value of x is: {}", x);

    // Shadowing also allows type changes
    let spaces = "   ";
    let spaces = spaces.len();  // Now spaces is a usize
    println!("Number of spaces: {}", spaces);
}

fn main() {
    // Signed integers (can be negative)
    let a: i8 = -128;       // 8-bit: -128 to 127
    let b: i16 = 1000;      // 16-bit
    let c: i32 = 100000;    // 32-bit (default)
    let d: i64 = 1000000;   // 64-bit
    let e: i128 = 10000000; // 128-bit

    // Unsigned integers (only positive)
    let f: u8 = 255;        // 8-bit: 0 to 255
    let g: u32 = 4000000;   // 32-bit unsigned

    // Architecture-dependent size
    let h: isize = 100;     // 32-bit on 32-bit systems, 64-bit on 64-bit
    let i: usize = 100;     // Same, but unsigned

    // Type inference works too
    let j = 42;             // Rust infers i32

    println!("a = {}, f = {}, j = {}", a, f, j);
}

fn main() {
    let x = 2.0;          // f64 (default, double precision)
    let y: f32 = 3.0;     // f32 (single precision)

    println!("x = {}, y = {}", x, y);

    // Floating-point operations
    let sum = x + y as f64;
    let product = x * 2.5;
    println!("sum = {}, product = {}", sum, product);
}

fn main() {
    // Boolean type
    let t = true;
    let f: bool = false;
    println!("t = {}, f = {}", t, f);

    // Character type (4 bytes, Unicode scalar value)
    let c = 'z';
    let z = 'ℤ';
    let heart = '❤';
    let emoji = '😀';

    println!("c = {}, z = {}, heart = {}, emoji = {}", c, z, heart, emoji);
}

fn main() {
    // A tuple with mixed types
    let tup: (i32, f64, &str) = (500, 6.4, "hello");

    // Destructuring a tuple
    let (x, y, z) = tup;
    println!("x = {}, y = {}, z = {}", x, y, z);

    // Accessing by index
    let first = tup.0;
    let second = tup.1;
    println!("first = {}, second = {}", first, second);

    // Unit type (empty tuple)
    let unit = ();
    println!("Unit type: {:?}", unit);
}

fn main() {
    // Array with explicit type and size
    let a: [i32; 5] = [1, 2, 3, 4, 5];

    // Array with repeated values
    let b = [3; 5];  // [3, 3, 3, 3, 3]

    // Accessing elements
    let first = a[0];
    let second = a[1];
    println!("first = {}, second = {}", first, second);

    // Array length
    println!("Array a has {} elements", a.len());

    // Iterating over an array
    for element in a {
        print!("{} ", element);
    }
    println!();
}

fn main() {
    println!("Hello from main!");

    // Calling another function
    say_hello();

    // Calling a function with parameters
    greet("Alice");

    // Calling a function that returns a value
    let result = add(5, 3);
    println!("5 + 3 = {}", result);
}

fn say_hello() {
    println!("Hello!");
}

fn greet(name: &str) {
    println!("Hello, {}!", name);
}

fn add(a: i32, b: i32) -> i32 {
    a + b  // No semicolon = expression (returns value)
}

fn main() {
    let x = 5;  // Statement: let binding

    // This is an expression block
    let y = {
        let a = 3;
        a + 1       // Expression (no semicolon) - returns 4
    };

    println!("x = {}, y = {}", x, y);

    // Function returning an expression
    let z = calculate();
    println!("z = {}", z);
}

fn calculate() -> i32 {
    let a = 10;
    let b = 20;
    a + b  // Expression: returns 30
    // a + b;  // With semicolon, this becomes a statement and causes an error!
}

fn main() {
    println!("abs(-5) = {}", absolute_value(-5));
    println!("abs(5) = {}", absolute_value(5));
    println!("max(10, 20) = {}", max(10, 20));
}

fn absolute_value(x: i32) -> i32 {
    if x < 0 {
        return -x;  // Early return
    }
    x  // Implicit return of the last expression
}

fn max(a: i32, b: i32) -> i32 {
    if a > b {
        return a;
    }
    b
}

fn main() {
    let num = 5;
    print_number(num);
    println!("num is still: {}", num);  // num is still valid

    let s = String::from("hello");
    print_string(&s);  // Pass a reference (borrowing)
    println!("s is still: {}", s);  // s is still valid
}

fn print_number(x: i32) {
    println!("The number is: {}", x);
}

fn print_string(s: &String) {
    println!("The string is: {}", s);
}

fn main() {
    let number = 7;

    // Basic if-else
    if number < 5 {
        println!("condition was true");
    } else {
        println!("condition was false");
    }

    // if with multiple branches
    if number % 4 == 0 {
        println!("number is divisible by 4");
    } else if number % 3 == 0 {
        println!("number is divisible by 3");
    } else if number % 2 == 0 {
        println!("number is divisible by 2");
    } else {
        println!("number is not divisible by 4, 3, or 2");
    }
}

fn main() {
    let condition = true;

    // if is an expression that returns a value
    let number = if condition { 5 } else { 6 };

    println!("The value of number is: {}", number);

    // Both branches must return the same type!
    // This would cause an error:
    // let x = if condition { 5 } else { "six" };
}

fn main() {
    let number = 3;

    match number {
        1 => println!("One!"),
        2 => println!("Two!"),
        3 => println!("Three!"),
        4 | 5 => println!("Four or Five!"),  // Multiple patterns
        6..=10 => println!("Between 6 and 10"),  // Range pattern
        _ => println!("Something else"),  // Catch-all pattern (required!)
    }

    // match can also return values
    let result = match number {
        1 => "first",
        2 => "second",
        3 => "third",
        _ => "other",
    };

    println!("Result: {}", result);
}

fn main() {
    let some_number = Some(5);

    // Using match (verbose)
    match some_number {
        Some(5) => println!("It's five!"),
        _ => (),
    }

    // Using if let (concise for single patterns)
    if let Some(5) = some_number {
        println!("It's five!");
    }

    // if let with else
    let favorite: Option<&str> = Some("Rust");
    if let Some(lang) = favorite {
        println!("Favorite language: {}", lang);
    } else {
        println!("No favorite language");
    }
}

fn main() {
    // loop — infinite loop
    let mut counter = 0;
    let result = loop {
        counter += 1;
        if counter == 10 {
            break counter * 2;  // Return a value from loop
        }
    };
    println!("Loop result: {}", result);

    // while loop
    let mut number = 3;
    while number != 0 {
        println!("{}!", number);
        number -= 1;
    }
    println!("LIFTOFF!!!");

    // for loop (iterating over a collection)
    let a = [10, 20, 30, 40, 50];
    for element in a {
        println!("The value is: {}", element);
    }

    // for with a range
    for number in 1..4 {
        println!("{}!", number);
    }

    // Range inclusive
    for number in 1..=3 {
        println!("{}!", number);
    }
}
